import pandas as pd

def clean(df):
    df = df.drop_duplicates().reset_index(drop=True)
    if 'island' in df.columns:
        df['island'] = df['island'].astype(str).str.strip()
    if 'body_mass_g' in df.columns:
        df['body_mass_g'] = df['body_mass_g'].astype(str).str.replace(',', '').str.strip()
        df['body_mass_g'] = pd.to_numeric(df['body_mass_g'], errors='coerce')
        mask_out = df['body_mass_g'] > 6500
        if mask_out.any():
            corrected = df.loc[mask_out, 'body_mass_g'] / 1000
            mask_correct = (corrected >= 2500) & (corrected <= 6500)
            df.loc[mask_out & mask_correct, 'body_mass_g'] = corrected[mask_correct]
    if 'sex' in df.columns:
        df = df[df['sex'].isin(['male', 'female'])].reset_index(drop=True)
    return df

def answer(df):
    result = df.groupby('sex')['body_mass_g'].mean().to_dict()
    return result
